package com.aditya.fefo.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="reservation_items") public class ReservationItem { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reservation_id",nullable=false) private Reservation reservation; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id",nullable=false) private Batch batch; @Column(nullable=false) private long quantity; @Column(name="created_at") private Instant createdAt; protected ReservationItem(){} public ReservationItem(Reservation r,Batch b,long q){this.id=UUID.randomUUID();this.reservation=r;this.batch=b;this.quantity=q;this.createdAt=Instant.now();} public UUID getId(){return id;} public Batch getBatch(){return batch;} public long getQuantity(){return quantity;} }
